TAIL=' Hand-painted 1990s point-and-click adventure game background, clean high-resolution digital gouache with visible brushwork. No people, no characters, no animals in the foreground, no text, no letters, no logos, no signs with writing.'
def prompt(k):
    l,place,floor,parts,_=S[k]
    return 'Extremely wide side-scrolling adventure game background, straight side-on view like a theater stage, camera level at eye height, everything seen flat from the front: '+place+', '+L[l][0]+'. A flat continuous strip of '+floor+' runs perfectly horizontally across the entire bottom fifth of the image, empty and unobstructed from the left edge to the right edge. Behind it from left to right: '+'; '.join(parts)+'.'+TAIL
def jprompt(c):
    return 'Extremely wide side-scrolling adventure game background, straight side-on view like a theater stage, camera level at eye height, buildings seen perfectly flat from the front and cropped at the top so that only the ground floor and the first upper floor are visible, doors about one third of the image height: '+J[c]+', at night after rain, warm lantern light, wet reflections. A flat continuous pavement runs perfectly horizontally across the entire bottom fifth of the image, empty and unobstructed from the left edge to the right edge. The row of similar facades continues evenly with no unique landmark and no vehicle, so the picture could repeat endlessly; the left and right image edges end in the middle of a plain wall.'+TAIL
ORDER=list(S.keys())+['jagd_'+c for c in J]
if __name__=='__main__':
    import json
    P={k:(prompt(k) if k in S else jprompt(k[5:])) for k in ORDER}
    json.dump({'order':ORDER,'p':P},open('pano_prompts.json','w'),ensure_ascii=False)
    print(len(ORDER),max(len(v) for v in P.values()))
